def transform(grid):
    from collections import Counter, defaultdict

    h, w = len(grid), len(grid[0])
    counts = Counter(
        grid[r][c]
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    )
    if not counts:
        return grid

    threshold = max(3, max(counts.values()) * 0.08)
    colors = {v for v, n in counts.items() if n >= threshold}

    transitions = defaultdict(Counter)
    for r in range(3, h):
        for c in range(3, w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a in colors and b in colors:
                transitions[a][b] += 1

    start = max(colors, key=lambda v: counts[v])
    cycle = []
    seen = set()
    cur = start
    while cur not in seen:
        cycle.append(cur)
        seen.add(cur)
        nxts = transitions[cur]
        if not nxts:
            break
        cur = nxts.most_common(1)[0][0]

    if len(cycle) != len(colors):
        # Recover any colors not reached in the dominant horizontal cycle.
        cycle.extend(sorted(colors - set(cycle)))

    index = {v: i for i, v in enumerate(cycle)}
    p = len(cycle)
    out = [row[:] for row in grid]

    for r in range(3, h):
        phases = Counter(
            (index[grid[r][c]] - c) % p
            for c in range(3, w)
            if grid[r][c] in index
        )
        phase = phases.most_common(1)[0][0] if phases else 0
        for c in range(w):
            if out[r][c] != 0:
                continue
            if c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                out[r][c] = cycle[(c + phase) % p]

    for r in range(min(3, h)):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = 1 if r < 2 or c < 2 else 4

    return out
